### 3. Frontend UI Component (Uptime Widget)

**File:** `/Users/rsoley/Dev/personal/rsrdev.com/components/sections/widgets-grid.tsx`

The `UptimeWidget` component consumes `opsStats` from the context and renders the status indicator, connections count, latency, and uptime.

```typescript
function UptimeWidget({ className }: WidgetProps) {
	const t = useTranslation()
	const { language } = useLanguage()
	const { opsStats, loading } = useWidgetData()
	const stats = opsStats

	const isOperational = stats?.status === "ok"
	const isDegraded = stats?.status === "degraded"
	const isDown = stats?.status === "issue"

	const pulseColor = isOperational
		? "bg-green-400"
		: isDegraded
			? "bg-amber-400"
			: "bg-red-400"
	const dotColor = isOperational
		? "bg-green-500"
		: isDegraded
			? "bg-amber-500"
			: "bg-red-500"

	const statusLabel =
		(language === "es" ? stats?.statusTextEs : stats?.statusText) ||
		stats?.statusText ||
		(isOperational
			? t.widgets.allSystemsOperational
			: isDegraded
				? t.widgets.someSystemsDegraded
				: t.widgets.systemIssuesDetected)

	return (
		<<Card className={cn("flex h-full flex-col", className)}>
			{/* ... header with status dot and external link ... */}
			<<CardContent className="flex flex-1 flex-col justify-between gap-4">
				<div className="flex items-center gap-2">
					{/* Animated status pulse dot */}
					<div className="relative flex h-3 w-3">
						<span className={cn("absolute inline-flex h-full w-full animate-ping rounded-full opacity-75", pulseColor)} />
						<span className={cn("relative inline-flex h-3 w-3 rounded-full", dotColor)} />
					</div>
					<span className="font-medium text-sm">{statusLabel}</span>
				</div>

				<div className="grid grid-cols-3 gap-4">
					<div className="flex flex-col gap-1">
						<span className="text-muted-foreground text-xs">{t.widgets.connections}</span>
						{loading.opsStats ? (
							<div className="h-6 w-16 animate-pulse rounded bg-muted" />
						) : (
							<span className="font-bold text-xl">{stats?.connections || 0}</span>
						)}
					</div>
					<div className="flex flex-col gap-1">
						<span className="text-muted-foreground text-xs">{t.widgets.latency}</span>
						{loading.opsStats ? (
							<div className="h-6 w-16 animate-pulse rounded bg-muted" />
						) : (
							<TooltipProvider delayDuration={100}>
								<Tooltip>
									<TooltipTrigger asChild>
										<span className="decoration-foreground/30 cursor-help font-bold text-xl underline decoration-dashed underline-offset-4">
											{stats?.ping || 0}ms
										</span>
									</TooltipTrigger>
									<TooltipContent ...>
										<p>{t.widgets.latencyTooltip}</p>
									</TooltipContent>
								</Tooltip>
							</TooltipProvider>
						)}
					</div>
					<div className="flex flex-col gap-1">
						<span className="text-muted-foreground text-xs">{t.widgets.uptime}</span>
						{loading.opsStats ? (
							<div className="h-6 w-16 animate-pulse rounded bg-muted" />
						) : (
							<a href="https://status.rsrdev.com/" ...>
								{stats?.uptime ? `${Number.parseFloat(stats.uptime).toFixed(2)}%` : "0%"}
							</a>
						)}
					</div>
				</div>
			</CardContent>
		</Card>
	)
}
